// 1. Get the raw text output from the model
const rawText = $input.item.json.content.parts[0].text;

// 2. Clean out Markdown code blocks if present (e.g. ```json ... ```)
const cleanedText = rawText.replace(/```json\n?|```/g, '').trim();

// 3. Parse the JSON string into an array of objects
const seedsArray = JSON.parse(cleanedText);

// 4. Map output items for n8n
return seedsArray.map(seed => {
  return {
    json: {
      seed_id: seed.seed_id || "",
      lifecycle_stage: seed.lifecycle_stage || "",
      primary_intent: seed.primary_intent || "",
      key_pain_points: Array.isArray(seed.key_pain_points)
        ? seed.key_pain_points.join(" | ")
        : (seed.key_pain_points || ""),
      contextual_barrier: seed.contextual_barrier || "",
      usage_count: 0,
      persona_cycle: 1
    }
  };
});

// Aggregate the 10 seeds into one single array payload
const allSelected = $input.all().map(item => item.json);

return [
  {
    json: {
      seed_batch_size: allSelected.length,
      seeds: allSelected
    }
  }
];

// 1. Get input from previous Gemini node
const inputData = $input.first().json;

// 2. Safely extract raw text string from Gemini response structure
let rawText = "";

if (inputData.content && inputData.content.parts && inputData.content.parts[0]) {
  rawText = inputData.content.parts[0].text || "";
} else if (inputData.parts && inputData.parts[0]) {
  rawText = inputData.parts[0].text || "";
} else if (typeof inputData.content === 'string') {
  rawText = inputData.content;
} else if (typeof inputData === 'string') {
  rawText = inputData;
}

if (!rawText) {
  throw new Error("Could not find raw text in Gemini response. Output structure: " + JSON.stringify(inputData));
}

// 3. Clean up markdown backticks if Gemini wrapped output in ```json ... ```
const cleanText = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();

// 4. Parse JSON string into JavaScript objects
let personasArray = [];

try {
  const parsed = JSON.parse(cleanText);
  // Un-nest if wrapped in an object like { "personas": [...] }
  if (Array.isArray(parsed)) {
    personasArray = parsed;
  } else if (parsed && typeof parsed === 'object') {
    personasArray = parsed.personas || parsed.hydrated_personas || parsed.data || Object.values(parsed).find(Array.isArray) || [];
  }
} catch (err) {
  throw new Error("Failed to parse Gemini output into JSON array: " + err.message + "\nRaw Text snippet: " + cleanText.substring(0, 150));
}

if (!Array.isArray(personasArray) || personasArray.length === 0) {
  throw new Error("Parsed output is not an array of personas.");
}

// 5. Current ISO Timestamp
const currentTimestamp = new Date().toISOString();

// 6. Map each persona into the Hybrid Table Schema
return personasArray.map((p, index) => {
  const nestedPayload = {
    demographics: p.demographics || {},
    behavioral_attributes: p.behavioral_attributes || {},
    context: {
      language: p.language || p.context?.language || "English",
      location_context: p.location_context || p.context?.location_context || ""
    },
    technical_profile: p.technical_profile || {}
  };

  return {
    json: {
      persona_id: p.persona_id || `PERS_${String(index + 1).padStart(2, '0')}`,
      lifecycle_stage: p.lifecycle_stage || "DISCOVERY",
      usage_count: 0,
      persona_title: p.persona_title || "Target Persona Profile",
      persona_json: JSON.stringify(nestedPayload),
      created_at: currentTimestamp
    }
  };
});

// Target provider tag
const TARGET_AI = "gemini";

// 1. Get today's 15 target prompts calculated upstream
const todays15Prompts = $("fetch_todays_prompts").all().map(item => item.json);

// 2. Get today's returns from the Gemini database query node
const existingReturns = $input.all().map(item => item.json);

const todayStrIso = $now.toFormat('yyyy-MM-dd');
const todayStrEur = $now.toFormat('dd.MM.yyyy');

// 3. Collect prompt_ids already processed today for THIS specific provider
const completedTodayIds = existingReturns
  .filter(r => {
    if (!r || !r.prompt_id) return false;

    // Match provider column (case-insensitive check)
    const provider = String(r.ai || "").toLowerCase().trim();
    if (provider && provider !== TARGET_AI) return false;

    // Match execution date
    const runDate = String(r.run_date || r.createdAt || r.date || "");
    if (!runDate || runDate === "undefined") return true; 

    return runDate.includes(todayStrIso) || runDate.includes(todayStrEur);
  })
  .map(r => r.prompt_id);

// 4. Exclude completed prompts
const remainingPrompts = todays15Prompts.filter(p => !completedTodayIds.includes(p.prompt_id));

return remainingPrompts.map(p => ({ json: p }));

// 1. Fetch settings dynamically
const settings = $('Edit Fields').first().json;
let rawStages = settings.relevant_lifestages || settings.relevant_stages || ["DISCOVERY", "COMPARISON", "BRAND TRUST"];
if (typeof rawStages === 'string') {
  rawStages = rawStages.split(',').map(s => s.trim());
}

// Helper: Normalize lifecycle stage strings (removes quotes, converts spaces/underscores)
function normalizeStage(stageStr) {
  return String(stageStr || '')
    .replace(/["']/g, '')
    .toUpperCase()
    .replace(/[\s_]+/g, '_')
    .trim();
}

// 2. Fetch all 45 incoming prompts from the active personas
const allPrompts = $input.all().map(item => item.json);

// 3. Dynamically group unique persona_ids by normalized lifecycle_stage
const stagesMap = {};
for (const stage of rawStages) {
  const cleanKey = normalizeStage(stage);
  if (cleanKey) stagesMap[cleanKey] = new Set();
}

for (const p of allPrompts) {
  const normalizedPStage = normalizeStage(p.lifecycle_stage);
  const personaId = p.persona_id;

  if (stagesMap[normalizedPStage] && personaId) {
    stagesMap[normalizedPStage].add(personaId);
  }
}

// 4. Calculate Day of the Year
const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 0);
const diff = now - startOfYear;
const oneDay = 1000 * 60 * 60 * 24;
const dayOfYear = Math.floor(diff / oneDay);

// 5. Select today's target Persona ID for each configured stage
const todaysPersonaIds = [];

for (const stage of rawStages) {
  const stageKey = normalizeStage(stage);
  const stagePersonas = Array.from(stagesMap[stageKey] || []).sort();

  if (stagePersonas.length > 0) {
    // Round-robin selection: dayOfYear modulo number of active personas in stage
    const selectedPersonaId = stagePersonas[dayOfYear % stagePersonas.length];
    todaysPersonaIds.push(selectedPersonaId);
  }
}

// 6. Filter all active prompts down to today's target personas (5 prompts x target personas)
const todaysTargetPrompts = allPrompts.filter(p => todaysPersonaIds.includes(p.persona_id));

// Return items ready for execution / generation batching
return todaysTargetPrompts.map(p => ({ json: p }));

// Target provider tag
const TARGET_AI = "chatgpt";

// 1. Get today's 15 target prompts calculated upstream
const todays15Prompts = $("fetch_todays_prompts").all().map(item => item.json);

// 2. Get today's returns from the Gemini database query node
const existingReturns = $input.all().map(item => item.json);

const todayStrIso = $now.toFormat('yyyy-MM-dd');
const todayStrEur = $now.toFormat('dd.MM.yyyy');

// 3. Collect prompt_ids already processed today for THIS specific provider
const completedTodayIds = existingReturns
  .filter(r => {
    if (!r || !r.prompt_id) return false;

    // Match provider column (case-insensitive check)
    const provider = String(r.ai || "").toLowerCase().trim();
    if (provider && provider !== TARGET_AI) return false;

    // Match execution date
    const runDate = String(r.run_date || r.createdAt || r.date || "");
    if (!runDate || runDate === "undefined") return true; 

    return runDate.includes(todayStrIso) || runDate.includes(todayStrEur);
  })
  .map(r => r.prompt_id);

// 4. Exclude completed prompts
const remainingPrompts = todays15Prompts.filter(p => !completedTodayIds.includes(p.prompt_id));

return remainingPrompts.map(p => ({ json: p }));

// 1. Get raw input from previous Gemini model node
const inputData = $input.first().json;

// 2. Safely extract raw text string from Gemini output
let rawText = "";

if (inputData.content && inputData.content.parts && inputData.content.parts[0]) {
  rawText = inputData.content.parts[0].text || "";
} else if (inputData.parts && inputData.parts[0]) {
  rawText = inputData.parts[0].text || "";
} else if (typeof inputData.content === 'string') {
  rawText = inputData.content;
} else if (typeof inputData === 'string') {
  rawText = inputData;
}

if (!rawText) {
  throw new Error("Could not find raw text in Gemini response.");
}

// 3. Clean markdown formatting backticks
let cleanText = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();

// 4. Handle truncated or incomplete JSON safely
// If the LLM cut off mid-array, close the JSON array string
if (!cleanText.endsWith("]")) {
  const lastObjectEnd = cleanText.lastIndexOf("}");
  if (lastObjectEnd !== -1) {
    cleanText = cleanText.substring(0, lastObjectEnd + 1) + "\n]";
  }
}

// 5. Parse JSON array
let promptsArray = [];

try {
  const parsed = JSON.parse(cleanText);
  if (Array.isArray(parsed)) {
    promptsArray = parsed;
  } else if (parsed && typeof parsed === 'object') {
    promptsArray = parsed.prompts || parsed.data || Object.values(parsed).find(Array.isArray) || [];
  }
} catch (err) {
  throw new Error("Failed to parse Prompts JSON array: " + err.message + "\nSnippet: " + cleanText.substring(0, 150));
}

if (!Array.isArray(promptsArray) || promptsArray.length === 0) {
  throw new Error("No valid prompt items found in response.");
}

// 6. Return mapped output items for n8n pipeline downstream
return promptsArray.map((p, index) => {
  return {
    json: {
      prompt_id: p.prompt_id || `PR_${String(index + 1).padStart(0, '0')}`,
      persona_id: p.persona_id || "UNKNOWN",
      lifecycle_stage: p.lifecycle_stage || "DISCOVERY",
      prompt_type: p.prompt_type || "Conversational",
      prompt_text: p.prompt_text || "",
    }
  };
});

// 1. Get all incoming seeds/personas
const allSelected = $input.all().map(item => item.json);

// 2. Define batch size
const BATCH_SIZE = 10;
const batches = [];

// 3. Chunk items into arrays of 10
for (let i = 0; i < allSelected.length; i += BATCH_SIZE) {
  const batch = allSelected.slice(i, i + BATCH_SIZE);
  batches.push({
    json: {
      batch_number: Math.floor(i / BATCH_SIZE) + 1,
      total_batches: Math.ceil(allSelected.length / BATCH_SIZE),
      seed_batch_size: batch.length,
      seeds: batch
    }
  });
}

// 4. Return array of 3 items (Batch 1: 10 items, Batch 2: 10 items, Batch 3: 10 items)
return batches;

// 1. Get all 3 original batches (10 personas / 50 prompts each)
const allBatches = $("batch_personas_in_10_item_batches").all().map(item => item.json);

// 2. Get already created prompts/returns from your database node
const existingPrompts = $input.all().map(item => item.json);

// 3. Collect persona_ids that ALREADY have prompts in the database today
const completedPersonaIds = new Set(
  existingPrompts
    .map(p => p.persona_id)
    .filter(Boolean)
);

// 4. Filter the 3 batches: keep only batches that have UNPROCESSED personas
const remainingBatches = [];

for (const batch of allBatches) {
  const seedsInBatch = batch.seeds || [];

  // Check if at least ONE persona in this batch is missing from the database
  const hasUnprocessedPersona = seedsInBatch.some(
    seed => !completedPersonaIds.has(seed.persona_id)
  );

  // If the batch contains unprocessed personas, keep it in the execution queue!
  if (hasUnprocessedPersona) {
    remainingBatches.push({ json: batch });
  }
}

// 5. Output only the batches that actually need execution
return remainingBatches;

// 1. Fetch settings dynamically
const settings = $('Edit Fields').first().json;

// Extract raw string or array
let rawStages = settings.relevant_lifestages ;
if (typeof rawStages === 'string') {
  rawStages = rawStages.split(',').map(s => s.trim());
}

const targetCountPerStage = Number(settings.weekly_cycle_number);

// 2. Extract personas directly from incoming input items
const allPersonas = $('Get row(s)4').all().map(item => item.json);

// Helper: Completely strip quotes, convert spaces to underscores, and uppercase
function normalizeStage(stageStr) {
  return String(stageStr || '')
    .replace(/["']/g, '')         // Removes literal double/single quotes
    .toUpperCase()
    .replace(/[\s_]+/g, '_')       // Normalizes spaces to underscores
    .trim();
}

// Helper: Fisher-Yates Shuffle
function shuffle(array) {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// 3. Dynamically group personas with clean keys
const stagesMap = {};
for (const stage of rawStages) {
  const cleanKey = normalizeStage(stage);
  if (cleanKey) stagesMap[cleanKey] = [];
}

for (const p of allPersonas) {
  const normalizedPStage = normalizeStage(p.lifecycle_stage);
  if (stagesMap[normalizedPStage]) {
    stagesMap[normalizedPStage].push(p);
  }
}

// 4. Dynamic Selection Function
function selectPersonasForStage(personasInStage, targetCount) {
  if (!personasInStage || personasInStage.length === 0) return [];

  const usageGroups = {};
  for (const p of personasInStage) {
    const count = Number(p.usage_count || 0);
    if (!usageGroups[count]) usageGroups[count] = [];
    usageGroups[count].push(p);
  }

  const sortedCounts = Object.keys(usageGroups).map(Number).sort((a, b) => a - b);
  const selected = [];

  for (const count of sortedCounts) {
    const randomizedGroup = shuffle(usageGroups[count]);
    for (const persona of randomizedGroup) {
      if (selected.length < targetCount) {
        selected.push(persona);
      }
    }
    if (selected.length >= targetCount) break;
  }

  return selected;
}

// 5. Select target count per stage
const selectedPersonas = [];
for (const stage of rawStages) {
  const stageKey = normalizeStage(stage);
  const pickedForStage = selectPersonasForStage(stagesMap[stageKey], targetCountPerStage);
  selectedPersonas.push(...pickedForStage);
}

// 6. Output formatted for Update row(s)
const updatedPersonas = selectedPersonas.map(p => {
  const currentUsage = Number(p.usage_count || 0);
  return {
    ...p,
    usage_count: currentUsage + 1,
    active_persona: "true"
  };
});

return updatedPersonas.map(p => ({ json: p }));

// 1. Fetch all 30 personas from input
const allPersonas = $input.all().map(item => item.json);

// Helper: Fisher-Yates Shuffle for random tie-breaking
function shuffle(array) {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// 2. Separate active vs inactive personas grouped by stage
const stages = ["DISCOVERY", "COMPARISON", "BRAND TRUST"];
const activeByStage = { "DISCOVERY": [], "COMPARISON": [], "BRAND TRUST": [] };
const inactiveByStage = { "DISCOVERY": [], "COMPARISON": [], "BRAND TRUST": [] };

for (const p of allPersonas) {
  const stage = (p.lifecycle_stage || "").toUpperCase().trim();
  const isActive = String(p.active_persona).toLowerCase() === "true";

  if (stages.includes(stage)) {
    if (isActive) {
      activeByStage[stage].push(p);
    } else {
      inactiveByStage[stage].push(p);
    }
  }
}

const dismissedPersonas = [];
const addedPersonas = [];

// 3. Process each stage: Dismiss 1 random active persona, Activate 1 lowest-used inactive persona
for (const stage of stages) {
  const activeList = activeByStage[stage];
  const inactiveList = inactiveByStage[stage];

  // A. Pick 1 active persona to dismiss (Random selection among current active ones)
  if (activeList.length > 0) {
    const randomDismissTarget = shuffle(activeList)[0];
    dismissedPersonas.push({
      ...randomDismissTarget,
      active_persona: "false",
      action_tag: "DISMISSED"
    });
  }

  // B. Pick 1 inactive persona to activate (Lowest usage_count first)
  if (inactiveList.length > 0) {
    // Group inactive personas by usage count
    const usageGroups = {};
    for (const p of inactiveList) {
      const count = Number(p.usage_count || 0);
      if (!usageGroups[count]) usageGroups[count] = [];
      usageGroups[count].push(p);
    }

    // Find lowest usage tier
    const lowestCount = Math.min(...Object.keys(usageGroups).map(Number));
    const lowestUsedCandidates = shuffle(usageGroups[lowestCount]);
    const chosenCandidate = lowestUsedCandidates[0];

    addedPersonas.push({
      ...chosenCandidate,
      active_persona: "true",
      usage_count: Number(chosenCandidate.usage_count || 0) + 1,
      action_tag: "ACTIVATED"
    });
  }
}

// 4. Combine all modified rows (3 dismissed + 3 activated = 6 rows to update in DB)
const allUpdates = [...dismissedPersonas, ...addedPersonas];

return allUpdates.map(p => ({ json: p }));
